function syncChips(){const p=state.profile;const mark=(sel,attr,list,aria)=>document.querySelectorAll(sel).forEach(n=>{const on=list.includes(n.dataset[attr]);n.classList.toggle('selected',on);n.setAttribute(aria,String(on));});mark('[data-topic]','topic',p.topics,'aria-checked');mark('[data-secondary-interest]','secondaryInterest',p.secondaryInterests,'aria-pressed');mark('[data-personal-interest]','personalInterest',p.personalInterests,'aria-pressed');const a=document.querySelector('[data-count="secondary"]');if(a)a.textContent=`${p.secondaryInterests.length} / 2 selected`;const b=document.querySelector('[data-count="personal"]');if(b)b.textContent=`${p.personalInterests.length} / 2 selected`;const next=document.querySelector('.wf-step-3 [data-action="secondary"]');if(next)next.disabled=!p.topics.length;}
function persist(){ try {localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Your browser could not save changes.');} }
function events(){return [...sampleEvents,...state.custom.map(e=>({kind:'event',price:0,currency:'USD',interests:[],...e}))];}
function getEvent(id){return events().find(e=>e.id===id);}
function topic(id){return topics.find(t=>t.id===id)||topics[0];}
function personalTopics(){return state.profile.topics.map(topic);}
function btn(label,action,kind='',extra=''){return `<button class="btn ${kind}" ${extra} data-action="${action}">${label}</button>`;}
let lastRoute=null;const trail=[],scrollMemo={};
function navigate(to,isBack=false,replace=false){if(sheet.open)sheet.close();if(to!==route){scrollMemo[route]=window.scrollY;if(!isBack&&!replace){trail.push(route);if(trail.length>50)trail.shift();}}route=to;if(replace)location.replace('#'+to);else location.hash=to;render();window.scrollTo({top:isBack?(scrollMemo[to]||0):0,behavior:'instant'});}
function goBack(fallback='home'){navigate(trail.length?trail.pop():fallback,true);}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800);}
function brand(){return `<span class="brand"><img class="chi-header-logo" src="assets/identity/chi-2027.svg" alt="CHI 2027"><span class="sr-only">Conference companion</span></span>`;}

function badgeArt(){const [a]=personalTopics();return `<div class="personal-badge">${state.profile.avatar?`<img class="profile-photo" src="${esc(state.profile.avatar)}" alt="Your profile photo">`:icon(a?.icon||'identity-ai')}</div>`;}

function tags(ids){return `<div class="tag-row">${ids.map(id=>`<span class="pill">${logo(topic(id).id)} ${esc(topic(id).name)}</span>`).join('')}</div>`;}
function eventCover(e, cls='', full=false){
  const id=['matcha','first','walk','ai','access','play'].includes(e.id)?e.id:'custom';
  return `<div class="gathering-cover cover-${id}${full?'':' cover-min'} ${cls}" aria-hidden="true"><div class="cover-symbol">${icon(e.icon||'spark')}</div>${full?`<div class="cover-type"><strong>${esc(e.title)}</strong></div>`:''}</div>`;
}
function hostIdentity(e){return `<span class="host-avatar">${esc(e.host.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><span class="host-text"><small>Hosted by</small><strong>${esc(e.host)}</strong></span>`;}
function welcome(){return `<div class="mobile-welcome"><header class="conference-masthead"><img src="assets/identity/chi-2027.svg" class="chi-wordmark" alt="CHI 2027"><p>For people shaping<br>human–computer interaction.</p></header><main><section class="onboarding-collage" aria-hidden="true">${[sampleEvents[0],sampleEvents[3],sampleEvents[1],sampleEvents[2],sampleEvents[5]].map((e,i)=>`<div class="collage-poster poster-${i}">${eventCover(e,'',true)}</div>`).join('')}<div class="collage-fade"></div></section><section class="mobile-welcome-copy"><p class="eyebrow">CHI 2027 COMPANION</p><h1>Meet people<br>who share<br><span>your interests.</span></h1><button class="welcome-next" data-action="start" aria-label="Get started">${icon('arrow')}</button><button class="text-button" data-action="login">Log in ${icon('arrow')}</button></section></main></div>`;}

function onboardShell(step,body,actions){return `<div class="wf-onboarding wf-step-${step} fade-in"><header class="wf-header"><button data-action="welcome" aria-label="Return to start">${brand()}</button><span class="wf-step-counter">${step} / 6</span></header><main class="wf-onboard-body"><div class="wf-question">${body}</div><div class="wf-onboard-actions">${actions}</div></main></div>`;}

function roleView(){return onboardShell(1,`<div class="wf-role-list">${[['attendee','calendar','Attendee','I’m attending CHI.','Plan around sessions and meet people with shared interests.'],['visitor','people','Visitor','I’m a visitor.','Browse community activities open to visitors.']].map(([id,i,k,h,p])=>`<button class="wf-role-card ${state.profile.role===id?'selected':''}" aria-pressed="${state.profile.role===id}" data-role="${id}"><span class="row between"><span class="eyebrow">${k}</span><span class="check-circle">${state.profile.role===id?icon('check'):''}</span></span><span class="role-illustration">${icon(i)}</span><strong>${h}</strong><span class="role-description">${p}</span><span class="role-continue">Continue ${icon('arrow')}</span></button>`).join('')}</div>`,`<button class="wf-back text-button" data-action="back" aria-label="Back">${icon('back')}</button>`);}

function interestsView(){return onboardShell(2,`<h1>About you</h1><label class="form-label" for="profile-name">First name</label><input id="profile-name" class="input" autocomplete="given-name" maxlength="35" placeholder="First name" value="${esc(state.profile.name)}"><label class="form-label" for="profile-last">Last name</label><input id="profile-last" class="input" autocomplete="family-name" maxlength="35" placeholder="Last name" value="${esc(state.profile.lastName||'')}"><label class="form-label" for="profile-email">Email</label><input id="profile-email" class="input" type="email" inputmode="email" autocomplete="email" maxlength="80" placeholder="you@example.com" value="${esc(state.profile.email||'')}">`,btn(`Continue ${icon('arrow')}`,'goals','wide')+`<button class="wf-back text-button" data-action="back" aria-label="Back">${icon('back')}</button>`);}
function goalsView(){return onboardShell(3,`<h1>Domain interest</h1><p class="muted">Choose the one domain that best represents your research interests.</p><section class="question-section"><div class="question-section-heading"><span>Required · Choose 1</span></div><div class="interest-options wf-chips" role="radiogroup" aria-label="Your research domain">${topics.map(t=>`<button class="interest-option ${state.profile.topics.includes(t.id)?'selected':''}" role="radio" aria-checked="${state.profile.topics.includes(t.id)}" data-topic="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div></section>`,btn(`Continue ${icon('arrow')}`,'secondary','wide',state.profile.topics.length?'':'disabled')+`<button class="wf-back text-button" data-action="back" aria-label="Back">${icon('back')}</button>`);}
function secondaryView(){return onboardShell(4,`<h1>Secondary interest</h1><p class="muted">Other research areas you follow.</p><section class="question-section"><div class="question-section-heading"><span>Optional · Choose up to 2</span></div><div class="interest-options wf-chips" aria-label="Secondary research interests">${topics.filter(t=>!state.profile.topics.includes(t.id)).map(t=>`<button class="interest-option ${state.profile.secondaryInterests.includes(t.id)?'selected':''}" aria-pressed="${state.profile.secondaryInterests.includes(t.id)}" data-secondary-interest="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div><div class="selection-count" data-count="secondary">${state.profile.secondaryInterests.length} / 2 selected</div></section>`,btn(`Continue ${icon('arrow')}`,'outside','wide')+`<button class="wf-back text-button" data-action="back" aria-label="Back">${icon('back')}</button>`);}
function outsideView(){return onboardShell(5,`<h1>Outside research</h1><p class="muted">Interests outside work. Used to suggest activities and people.</p><section class="question-section"><div class="question-section-heading"><span>Optional · Choose up to 2</span></div><div class="interest-options wf-chips" aria-label="Personal interests">${personalInterests.map(t=>`<button class="interest-option ${state.profile.personalInterests.includes(t.id)?'selected':''}" aria-pressed="${state.profile.personalInterests.includes(t.id)}" data-personal-interest="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div><div class="selection-count" data-count="personal">${state.profile.personalInterests.length} / 2 selected</div></section>`,btn(`Create my profile ${icon('arrow')}`,'make-badge','wide')+`<button class="wf-back text-button" data-action="back" aria-label="Back">${icon('back')}</button>`);}

function badgeView(){return `<div class="profile-setup"><header class="profile-setup-top"><button class="icon-button" data-action="outside" aria-label="Back">${icon('back')}</button><button class="profile-done" data-action="finish" aria-label="Save profile and continue">${icon('check')}</button></header><main><div class="profile-introduction"><div class="profile-avatar-wrap">${badgeArt()}<button class="avatar-edit" data-action="change-avatar" aria-label="Choose a profile photo">${icon('plus')}</button><input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><h1>Complete Your Profile</h1><p>Introduce yourself to others at CHI.</p></div><div class="profile-fields"><label class="form-label" for="profile-name">First name</label><input id="profile-name" class="input" autocomplete="given-name" placeholder="First name" maxlength="35" value="${esc(state.profile.name)}"><label class="form-label" for="profile-last">Last name</label><input id="profile-last" class="input" autocomplete="family-name" placeholder="Last name" maxlength="35" value="${esc(state.profile.lastName||'')}"><p class="form-label" id="pos-label">I am a… <span class="muted">(optional)</span></p><div class="pos-chips" role="group" aria-labelledby="pos-label">${POSITIONS.map(p=>`<button type="button" class="pos-chip ${state.profile.position===p?'on':''}" data-position="${p}" aria-pressed="${state.profile.position===p}">${p}</button>`).join('')}</div><label class="form-label" for="profile-bio">Bio</label><textarea id="profile-bio" class="input" placeholder="Short bio (optional)" maxlength="240">${esc(state.profile.bio||'')}</textarea><p class="profile-selected-interest">${icon(personalTopics()[0]?.icon||'identity-ai')} ${esc(personalTopics()[0]?.name||'Your interest')}</p></div></main></div>`;}

