const navItems=[['home','home','For you'],['events','calendar','Activities'],['map','map','Map'],['plan','bookmark','Plan'],['profile','person','Badge']];
function shell(content,active='home',{tabs=true,header=true,footer=''}={}){return `<div class="shell wf-shell${tabs?' has-tabs':''}${header?'':' no-header'}">${header?`<header class="wf-header app-header"><button class="brand-button" data-action="home" aria-label="CHI Together home">${brand()}</button><button class="header-action" data-action="create" aria-label="Create an event">${icon('plus')}<span>Create</span></button></header>`:''}<main class="main fade-in" data-view="${active}">${content}</main>${footer}${tabs?tabbar(active):''}</div>`;}
function tabbar(active){return `<nav class="tabbar" aria-label="Main navigation">${navItems.map(([r,i,l])=>`<button data-action="${r}" class="${active===r?'active':''}"${active===r?' aria-current="page"':''}>${icon(i)}<span>${l}</span>${r==='plan'&&state.saved.length?`<b class="tab-count">${state.saved.length}</b>`:''}</button>`).join('')}</nav>`;}
function syncTabCount(){const b=document.querySelector('.tabbar [data-action="plan"]');if(!b)return;b.querySelector('.tab-count')?.remove();if(state.saved.length)b.insertAdjacentHTML('beforeend',`<b class="tab-count">${state.saved.length}</b>`);}
function syncSaved(id){const on=state.saved.includes(id);document.querySelectorAll(`.erow-save[data-save="${CSS.escape(id)}"]`).forEach(n=>{n.classList.toggle('saved',on);n.setAttribute('aria-pressed',String(on));n.setAttribute('aria-label',`${on?'Remove':'Save'} ${getEvent(id)?.title||''}`);n.innerHTML=icon(on?'bookmarkFilled':'bookmark');});if(filter==='saved'&&document.querySelector('#event-results'))document.querySelector('#event-results').innerHTML=resultsMarkup();}
function intro(kicker,title,description,aside=''){return `<div class="page-intro">${kicker?`<p class="eyebrow">${kicker}</p>`:''}<div class="row between"><h1>${title}</h1>${aside}</div>${description?`<p>${description}</p>`:''}</div>`;}
function eventRow(e){const saved=state.saved.includes(e.id);const t=topic(e.topic);const closed=['Full','Cancelled'].includes(e.status);return `<article class="erow"><button class="erow-main" data-event="${esc(e.id)}"><span class="erow-thumb">${eventCover(e)}</span><span class="erow-body"><span class="erow-kicker">${icon(t.icon)}<span>${esc(t.name)}</span></span><strong class="erow-title">${esc(e.title)}</strong><span class="erow-meta">${icon('clock')}<span class="erow-when">May ${e.day} · ${e.start}–${e.end}</span>${closed?`<span class="erow-status">${esc(e.status)}</span>`:''}</span><span class="erow-meta">${icon('pin')}<span class="erow-where">${esc(e.place)}</span><span class="erow-price">${priceLabel(e)}</span></span></span></button><button class="erow-save${saved?' saved':''}" data-save="${esc(e.id)}" aria-label="${saved?'Remove':'Save'} ${esc(e.title)}" aria-pressed="${saved}">${icon(saved?'bookmarkFilled':'bookmark')}</button></article>`;}

function plural(n,w,ws){return `${n} ${n===1?w:(ws||w+'s')}`;}
function homeSummary(available){const open=available.filter(e=>e.kind!=='paper').length;const parts=[`${plural(open,'gathering')} open`,`${state.saved.length} in your plan`];const reg=Object.keys(state.registrations).length;if(reg)parts.push(`${reg} registered`);return parts.join(' · ');}
function homeView(){const available=events().filter(e=>!['Cancelled','Full'].includes(e.status));const ranked=available.map((e,index)=>({e,index,score:(e.tags.some(t=>state.profile.topics.includes(t))?3:0)+(e.tags.some(t=>state.profile.secondaryInterests.includes(t))?1.5:0)+(e.interests||[]).filter(t=>state.profile.personalInterests.includes(t)).length})).sort((a,b)=>b.score-a.score||a.index-b.index);const recommended=(ranked[0]||{e:sampleEvents[0]}).e;const others=ranked.filter(x=>x.e.kind!=='paper'&&x.e.id!==recommended.id).slice(0,4).map(x=>x.e);return shell(`<section class="wf-home-intro"><h1>Hello, ${esc(state.profile.name||'Alex')}.</h1><p>${homeSummary(available)}</p></section><section class="planc-recommended" aria-label="Your top recommendation"><button class="planc-hero" data-event="${recommended.id}" aria-label="View recommended activity: ${esc(recommended.title)}">${eventCover(recommended)}<div class="planc-hero-copy"><span class="recommendation-label">${icon('spark')} PICKED FOR YOU</span><span class="hero-price">${priceLabel(recommended)}</span><h2>${esc(recommended.title)}</h2><span>May ${recommended.day} · ${recommended.start} ${icon('arrow')}</span></div></button></section><button class="planc-map-entry" data-action="map"><span class="map-entry-art" aria-hidden="true"><i></i><i></i><i></i>${icon('pin')}</span><span><strong>Explore the map</strong><span>See who’s nearby ${icon('arrow')}</span></span></button><section class="home-section"><div class="home-section-heading"><h2>More for you</h2><button class="text-button" data-action="events">See all ${icon('arrow')}</button></div><div class="erow-list">${others.map(e=>eventRow(e)).join('')}</div></section><section class="home-section"><h2>Browse by domain</h2><div class="domain-grid">${topics.map(t=>`<button data-home-filter="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div></section><section class="home-section"><div class="home-section-heading"><h2>From the programme</h2><span class="pill">Example</span></div><div class="erow-list">${eventRow(sampleEvents.find(e=>e.kind==='paper'))}</div></section>`);}

function filteredEvents(){return events().filter(e=>(filter==='all'||(filter==='saved'?state.saved.includes(e.id):e.tags.includes(filter)))&&(day==='all'||e.day===day)&&(!search||`${e.title} ${e.place} ${e.type} ${e.tags.map(t=>topic(t).name)}`.toLowerCase().includes(search.toLowerCase())));}
function resultsMarkup(){const result=filteredEvents();return result.length?result.map(e=>eventRow(e)).join(''):`<div class="empty">${icon('search')}<h3>No activities match.</h3><p>Try another filter or search term.</p>${btn('Clear filters','clear-filters','secondary')}</div>`;}
function eventsView(){return shell(`<section class="page-head"><h1>Activities</h1><div class="search">${icon('search')}<input id="event-search" type="search" aria-label="Search activities" placeholder="Search activities and interests" value="${esc(search)}"></div></section><div class="filters-bar"><div class="filters" role="group" aria-label="Filter by interest">${[['all','All'],...topics.map(t=>[t.id,t.name]),['saved','Saved']].map(([id,n])=>`<button class="filter ${filter===id?'active':''}" aria-pressed="${filter===id}" data-filter="${id}">${n}</button>`).join('')}</div></div><div class="erow-list" id="event-results">${resultsMarkup()}</div>`,'events');}

function crowdMapArtwork(){let h=7;const rnd=()=>{h=(h*1103515245+12345)&0x7fffffff;return h/0x7fffffff;};const tones=['#e6e3dc','#e1ded6','#e9e6df','#dedbd3'];let blocks='';for(let r=-5;r<13;r++)for(let c=-4;c<10;c++){const x=c*150,y=r*150,n=1+Math.floor(rnd()*3);for(let k=0;k<n;k++){const w=(118/n),bx=x+16+k*w+(k?3:0),by=y+16+rnd()*8,bw=w-(k?3:0)-3,bh=104-rnd()*22;blocks+=`<rect x="${bx.toFixed(0)}" y="${by.toFixed(0)}" width="${bw.toFixed(0)}" height="${bh.toFixed(0)}" rx="3" fill="${tones[Math.floor(rnd()*4)]}"/>`;}}return `<svg class="crowd-base-map" viewBox="-400 -600 1600 2400" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect x="-400" y="-600" width="1600" height="2400" fill="#f0efe9"/><g transform="rotate(-14 400 600)">${blocks}</g><path d="M-500 1020L-60 1010C120 930 260 1040 430 990S690 880 880 930L1300 960V2000H-500Z" fill="#cfe1ea"/><path d="M-60 1010C120 930 260 1040 430 990S690 880 880 930" fill="none" stroke="#bcd3df" stroke-width="3"/><path d="M60 560q-4-60 60-70 70-8 90 40 18 50-40 80-70 30-110-10Z" fill="#d9e8d0"/><path d="M520 150q60-40 140 0 40 40-10 80-80 30-130-10-20-30 0-70Z" fill="#d9e8d0"/><g fill="none" stroke-linecap="round"><path d="M-400 190L1300 568M-400 636L1300 939" stroke="#d6d2c6" stroke-width="30"/><path d="M-400 190L1300 568M-400 636L1300 939" stroke="#fff6dd" stroke-width="24"/><path d="M158 -700L657 2000" stroke="#d6d2c6" stroke-width="26"/><path d="M158 -700L657 2000" stroke="#fff" stroke-width="20"/><path d="M-400 416L1300 718M595 -700L823 2000M0 -700L257 2000" stroke="#fff" stroke-width="12"/></g><rect x="300" y="500" width="170" height="130" rx="8" fill="#d8d4ca" stroke="#c9c5ba" stroke-width="2" transform="rotate(-8 385 565)"/><g class="map-labels"><text x="470" y="1120" transform="rotate(-5 470 1120)">Allegheny River</text><text x="140" y="535">Park</text><text x="395" y="571" transform="rotate(-8 395 571)">Convention Center</text><text x="610" y="388" transform="rotate(12 610 388)">Liberty Ave</text></g><path d="M360 960l60-30" stroke="#c9c5ba" stroke-width="14"/></svg>`;}
function visibleCrowdPeople(){return filterMapPeople(demoPeople,crowdState,state.profile);}
function mapView(){const people=visibleCrowdPeople();const groups=crowdGroups.map(g=>({...g,count:people.filter(p=>p.group===g.id).length})).filter(g=>g.count);const activityList=events().filter(e=>e.status!=='Cancelled'&&(crowdState.domain==='all'||e.tags.includes(crowdState.domain)));return shell(`<section class="crowd-map" data-level="${crowdState.zoom>=1.8?'people':'overview'}"><div class="crowd-viewport" tabindex="0" role="region" aria-label="Interactive example crowd map. Pinch or use zoom buttons to explore."><div class="crowd-world" style="--map-inverse:${1/crowdState.zoom}">${crowdMapArtwork()}<div class="crowd-heat-layer">${groups.map(g=>`<span class="crowd-heat" style="left:${g.x}%;top:${g.y}%;--heat-size:${80+g.count*4}px;--domain-shade:${g.shade}"></span>`).join('')}</div><div class="crowd-cluster-layer">${groups.map(g=>`<button class="crowd-cluster" data-crowd-group="${g.id}" style="left:${g.x}%;top:${g.y}%;--domain-shade:${g.shade}" aria-label="Explore ${esc(topic(g.topic).name)}, ${g.count} example people"><span class="cluster-symbol">${logo(topic(g.topic).id)}<b>${g.count}</b></span><span class="cluster-domain-label">${esc(topic(g.topic).name)}</span></button>`).join('')}</div><div class="crowd-person-layer">${people.map(p=>`<button class="person-marker ${crowdState.selectedPerson===p.id?'selected':''}" data-crowd-person="${p.id}" aria-label="View ${esc(p.name)}, ${esc(topic(p.topic).name)}" aria-pressed="${crowdState.selectedPerson===p.id}" style="left:${p.x}%;top:${p.y}%;--domain-shade:${p.shade};--person-color:${p.color}"></button>`).join('')}</div>${crowdState.activities?`<div class="crowd-activity-layer">${activityList.map(e=>`<button class="crowd-event-pin" data-event="${esc(e.id)}" style="left:${e.x}%;top:${e.y}%" aria-label="Open gathering ${esc(e.title)}">${icon('calendar')}<small>${esc(e.title)}</small></button>`).join('')}</div>`:''}<span class="map-you-marker" style="left:50%;top:57%"><img src="assets/wireframe/location.svg" alt="Your location"><small>You</small></span></div></div><div class="crowd-map-caption"><div class="map-status"><span class="map-stage-pill" data-map-level>${crowdState.zoom>=1.8?'Nearby people':'Crowd overview'}</span><p>${people.length} people · ${groups.length} ${groups.length===1?'group':'groups'}</p></div><small data-map-hint>${crowdState.zoom>=1.8?'Tap a person':'Pinch or tap + to zoom'}</small></div>${!people.length?`<div class="crowd-empty">${crowdState.people?'No people match these filters.':'People layer is hidden.'}<small>${crowdState.activities?'Activity pins are still available.':'Try changing the filters.'}</small></div>`:''}<div class="map-person-slot">${crowdPersonCard()}</div><details class="crowd-filters" ${crowdState.filtersOpen?'open':''}><summary>${icon('filter')}<span>Filters</span>${crowdState.domain!=='all'||crowdState.shared?'<i class="filter-dot" aria-label="Filters applied"></i>':''}</summary><div class="crowd-filter-panel"><h2>Show on the map</h2><label class="map-layer-choice"><span>${icon('people')} People</span><input class="switch" type="checkbox" id="map-people" ${crowdState.people?'checked':''}></label><label class="map-layer-choice"><span>${icon('calendar')} Activities</span><input class="switch" type="checkbox" id="map-activities" ${crowdState.activities?'checked':''}></label><label class="map-layer-choice shared-map-choice"><span>${icon('heart')} Shared interests only</span><input class="switch" type="checkbox" id="map-shared" ${crowdState.shared?'checked':''}></label><p class="form-label">Research domain</p><div class="map-domain-key" role="group" aria-label="Research domain">${[{id:'all',name:'All domains',color:'#1b1b1b',ic:''},...crowdGroups.map(g=>({id:g.topic,name:topic(g.topic).name,color:g.color,ic:topic(g.topic).icon}))].map(d=>`<button type="button" class="domain-chip ${crowdState.domain===d.id?'on':''}" data-map-domain="${d.id}" aria-pressed="${crowdState.domain===d.id}" style="--dc:${d.color}"><span class="dc-ic">${d.ic?logo(d.id):'<i></i>'}</span>${esc(d.name)}</button>`).join('')}</div></div></details><div class="crowd-zoom-controls" aria-label="Map zoom controls"><button data-crowd-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><span data-map-zoom-label>${crowdState.zoom.toFixed(1)}×</span><button data-crowd-action="zoom-out" aria-label="Zoom out" ${crowdState.zoom<=1?'disabled':''}><span aria-hidden="true">−</span></button><button class="map-recenter" data-crowd-action="reset" aria-label="Reset map view">${icon('pin')}</button></div></section>`,'map');}
function mutualCrowdInterests(person){const domains=[...state.profile.topics,...state.profile.secondaryInterests];return [...new Set([...domains.filter(id=>[person.topic,person.secondary].includes(id)).map(id=>topic(id).name),...state.profile.personalInterests.filter(id=>person.personalInterests.includes(id)).map(id=>personalInterests.find(t=>t.id===id)?.name).filter(Boolean)])];}
function crowdPersonCard(){const person=demoPeople.find(p=>p.id===crowdState.selectedPerson);if(!person||!visibleCrowdPeople().some(p=>p.id===person.id))return '';const shared=mutualCrowdInterests(person);return `<article class="map-person-card"><button class="person-card-close" data-crowd-action="close-person" aria-label="Close participant details">${icon('close')}</button><div class="person-card-heading"><span class="person-card-avatar" style="--domain-shade:${person.shade}">${logo(topic(person.topic).id)}</span><div><h2>${esc(person.name)}</h2><p>${esc(person.role)}</p></div></div><span class="person-domain">${logo(topic(person.topic).id)}${esc(topic(person.topic).name)}</span><p class="person-card-shared">${shared.length?`Shared: ${shared.map(esc).join(' · ')}`:'No shared interests yet.'}</p><button class="btn wide" data-crowd-profile="${person.id}">View profile ${icon('arrow')}</button></article>`;}
function refreshCrowdSelection(){const slot=document.querySelector('.map-person-slot');if(slot)slot.innerHTML=crowdPersonCard();document.querySelectorAll('[data-crowd-person]').forEach(node=>{const selected=node.dataset.crowdPerson===crowdState.selectedPerson;node.classList.toggle('selected',selected);node.setAttribute('aria-pressed',String(selected));});}
function showCrowdProfile(id){const person=demoPeople.find(p=>p.id===id);if(!person)return;const shared=mutualCrowdInterests(person);showSheet(`<div class="crowd-profile"><p class="eyebrow">EXAMPLE PROFILE</p><span class="person-profile-avatar" style="--domain-shade:${person.shade}">${logo(topic(person.topic).id)}</span><h2>${esc(person.name)}</h2><p>${esc(person.role)} · ${esc(person.place)}</p><span class="pill">${icon(person.open?'chat':'people')}${person.open?'Open to a conversation':'Happy to join and listen'}</span><p class="form-label">DOMAIN INTEREST</p>${tags([person.topic])}<p class="form-label">SECONDARY INTEREST</p>${tags([person.secondary])}<p class="form-label">OUTSIDE RESEARCH</p><div class="tag-row">${person.personalInterests.map(id=>{const t=personalInterests.find(t=>t.id===id);return `<span class="pill">${icon(t.icon)}${esc(t.name)}</span>`;}).join('')}</div><p class="person-profile-bio">Interested in ${esc(topic(person.topic).name.toLowerCase())}.</p>${shared.length?`<div class="mutual-interests"><strong>Shared interests</strong><p>${shared.map(esc).join(' · ')}</p></div>`:''}<p class="form-label">CONVERSATION STARTER</p><div class="quote">“What’s one question you brought to CHI this year?”</div></div>`,'Participant profile');}
function handleCrowdMapAction(el){if(el.dataset.crowdGroup){const group=crowdGroups.find(g=>g.id===el.dataset.crowdGroup);if(group){crowdState.selectedPerson=null;refreshCrowdSelection();crowdController?.focus(group.x,group.y,2.8);}return true;}if(el.dataset.crowdPerson){crowdState.selectedPerson=el.dataset.crowdPerson;refreshCrowdSelection();return true;}if(el.dataset.crowdProfile){showCrowdProfile(el.dataset.crowdProfile);return true;}if(el.dataset.crowdAction){switch(el.dataset.crowdAction){case'zoom-in':crowdController?.zoomIn();break;case'zoom-out':crowdController?.zoomOut();if(crowdState.zoom<1.8){crowdState.selectedPerson=null;refreshCrowdSelection();}break;case'reset':crowdState.selectedPerson=null;refreshCrowdSelection();crowdController?.reset();break;case'close-person':crowdState.selectedPerson=null;refreshCrowdSelection();break;}return true;}return false;}
document.addEventListener('click',event=>{const pb=event.target.closest('[data-position]');if(pb){state.profile.position=state.profile.position===pb.dataset.position?'':pb.dataset.position;persist();document.querySelectorAll('[data-position]').forEach(n=>{const on=n.dataset.position===state.profile.position;n.classList.toggle('on',on);n.setAttribute('aria-pressed',String(on));});return;}const b=event.target.closest('[data-map-domain]');if(!b)return;crowdState.domain=crowdState.domain===b.dataset.mapDomain?'all':b.dataset.mapDomain;crowdState.selectedPerson=null;render();});
document.addEventListener('change',event=>{const el=event.target;const field={'map-people':'people','map-activities':'activities','map-domain':'domain','map-shared':'shared'}[el.id];if(!field)return;crowdState[field]=el.id==='map-domain'?el.value:el.checked;crowdState.selectedPerson=null;render();});

function detailView(id){const e=getEvent(id);if(!e)return shell(`<div class="empty"><h2>This activity isn’t available.</h2>${btn('Browse activities','events')}</div>`,'events');const registration=state.registrations[id];const paper=e.kind==='paper';const closed=['Full','Cancelled'].includes(e.status);const primary=paper?`<button class="event-primary-action" data-calendar="${esc(id)}">${icon('calendar')}<span>Add to Calendar</span></button>`:registration?`<button class="event-primary-action" data-ticket="${esc(id)}">${icon('bookmark')}<span>My Ticket</span></button>`:`<button class="event-primary-action" data-register="${esc(id)}" ${closed?'disabled':''}>${closed?'':icon('plus')}<span>${closed?esc(e.status):'Register'}</span></button>`;const cta=`<div class="event-cta"><div class="event-cta-info"><strong>${priceLabel(e)}</strong><span>May ${e.day} · ${e.start}</span></div>${primary}</div>`;return shell(`<div class="event-detail"><div class="event-detail-toolbar"><button class="icon-button" data-action="back" aria-label="Back">${icon('back')}</button><button class="icon-button" data-share="${esc(id)}" aria-label="Share activity">${icon('share')}</button></div><div class="event-detail-cover">${eventCover(e)}</div><div class="event-detail-heading"><p class="eyebrow">${esc(e.type)}</p><h1>${esc(e.title)}</h1><p class="detail-date">May ${e.day}, 2027 · ${e.start}–${e.end}<small>Pittsburgh time · EDT</small></p></div><div class="event-secondary"><button data-save="${esc(id)}" class="save-toggle" aria-pressed="${state.saved.includes(id)}">${icon(state.saved.includes(id)?'bookmarkFilled':'bookmark')}<span>${state.saved.includes(id)?'Saved':'Save'}</span></button><button data-contact="${esc(id)}">${icon('chat')}<span>Contact</span></button></div>${!paper&&!registration?'<p class="event-access-note">Registration required, even for free events. Saving doesn’t reserve a place.</p>':''}<section class="event-location"><h2>Location</h2><strong>${esc(e.place)}</strong><button class="event-location-preview" data-locate="${esc(id)}">${icon('map')}<span>Find the meeting point</span>${icon('arrow')}</button></section><section class="event-about"><h2>About this ${paper?'session':'gathering'}</h2><p>${esc(e.description)}</p><p>${esc(e.expect)}</p><div class="event-host-block">${hostIdentity(e)}</div>${tags(e.tags)}</section></div>`,'detail',{tabs:false,header:false,footer:cta});}

function planView(){const list=events().filter(e=>state.saved.includes(e.id)).sort((a,b)=>Number(a.day)-Number(b.day)||a.start.localeCompare(b.start));const days=[...new Set(list.map(e=>e.day))];return shell(`${intro('','My plan','')}<div class="row between plan-head">${list.length?`<p class="plan-count">${list.length} ${list.length===1?'activity':'activities'}${Object.keys(state.registrations).filter(id=>state.saved.includes(id)).length?` · ${Object.keys(state.registrations).filter(id=>state.saved.includes(id)).length} registered`:''}</p>`:'<span></span>'}${btn(`${icon('plus')} Browse activities`,'events','secondary')}</div>${list.length?days.map(d=>`<section class="plan-day"><div class="date-tile"><span>May</span><strong>${d}</strong><span>${['Mon','Tue','Wed','Thu','Fri'][Number(d)-10]||''}</span></div><div class="plan-list">${list.filter(e=>e.day===d).map(e=>`<article class="plan-item"><span class="plan-symbol">${icon(e.icon)}</span><button class="info" style="text-align:left" data-event="${esc(e.id)}"><small>${esc(e.start)}–${esc(e.end)} ${e.status==='Cancelled'?'· CANCELLED':''}</small><h3>${esc(e.title)}</h3><small>${esc(e.place)}</small>${state.registrations[e.id]?'<small class="plan-registration-label">Registered · Demo ticket</small>':''}</button><div class="plan-actions"><button data-calendar="${esc(e.id)}" aria-label="Add ${esc(e.title)} to calendar">${icon('calendar')}</button><button data-save="${esc(e.id)}" aria-label="Remove ${esc(e.title)} from plan">${icon('close')}</button></div></article>`).join('')}</div></section>`).join(''):`<div class="card empty">${icon('bookmark')}<h2>Nothing saved yet.</h2><p>Saved activities appear here.</p>${btn('Browse activities','events')}</div>`}`,'plan');}
function profileView(){return shell(`${intro('','My badge','')}<div class="profile-layout"><div class="stack"><div class="badge-hero">${badgeArt()}<h2>${esc(fullName('Alex'))}</h2>${state.profile.position?`<p class="badge-position">${esc(state.profile.position)}</p>`:''}<p>${personalTopics().map(t=>esc(t.name)).join(' × ')||'Curious about CHI'}</p>${state.profile.bio?`<p class="profile-bio-display">${esc(state.profile.bio)}</p>`:''}<span class="pill" style="position:relative;margin-top:18px;background:white">${icon(state.profile.open?'chat':'people')}${state.profile.open?'Open to a conversation':'Happy to join and listen'}</span></div>${btn(`${icon('share')} Show my badge`,'show-badge','secondary')}${btn(`${icon('download')} Download badge`,'download','outline')}</div><div class="stack"><div><p class="form-label" style="margin-top:0">MY DOMAIN</p><div class="settings-card">${personalTopics().map(t=>`<div class="group-row"><span class="row">${icon(t.icon)}${t.name}</span>${icon('check')}</div>`).join('')}<button class="group-row" style="width:100%;text-align:left" data-action="edit-interests">Edit interests ${icon('chevron')}</button></div></div><div><p class="form-label">MY PREFERENCES</p><div class="settings-card"><div class="group-row"><label for="profile-open">Open to a conversation<small>Shown on your badge.</small></label><input id="profile-open" class="switch" type="checkbox" ${state.profile.open?'checked':''}></div><div class="group-row"><label for="profile-visible">Show interest badge<small>Your exact location is never shared.</small></label><input id="profile-visible" class="switch" type="checkbox" ${state.profile.visible?'checked':''}></div><button class="group-row" style="width:100%;text-align:left" data-action="stage-toggle">Conference view <span class="muted small">${state.stage==='before'?'Before CHI':'At CHI'} ${icon('chevron')}</span></button></div></div><div><p class="form-label">LOOKING TO</p>${state.profile.goals.map(g=>`<p class="small muted" style="margin:8px 0">${icon('check')} ${esc(g)}</p>`).join('')}</div><button class="text-button small" style="align-self:flex-start" data-action="reset">${icon('reset')} Start the prototype again</button></div></div>`,'profile');}
function createView(){const d=draft||{title:'',day:'10',start:'12:30',end:'13:15',place:'',topic:state.profile.topics[0]||'health',capacity:'12',description:'',host:state.profile.name||'Alex'};return shell(`<div class="create-layout"><button class="text-button small row" data-action="back">${icon('back')} Back</button><header class="create-intro"><h1>Create an event</h1></header><form id="create-form"><div class="wf-create-cover">${eventCover({...sampleEvents[0],id:'custom',title:d.title||'Your next gathering',icon:'coffee'})}</div><div class="card"><label class="form-label" for="activity-title">Activity name</label><input id="activity-title" name="title" class="input" placeholder="e.g. Coffee chat on accessibility" required maxlength="80" value="${esc(d.title)}"><div class="form-row"><div><label class="form-label" for="activity-day">Day in May 2027</label><select id="activity-day" name="day" class="select">${['10','11','12','13','14'].map(x=>`<option value="${x}" ${d.day===x?'selected':''}>May ${x}</option>`).join('')}</select></div><div><label class="form-label" for="activity-capacity">Capacity</label><input id="activity-capacity" name="capacity" type="number" class="input" min="2" max="100" value="${esc(d.capacity)}" required></div></div><div class="form-row"><div><label class="form-label" for="activity-start">Starts</label><input id="activity-start" class="input" type="time" name="start" value="${esc(d.start)}" required></div><div><label class="form-label" for="activity-end">Ends</label><input id="activity-end" class="input" type="time" name="end" value="${esc(d.end)}" required></div></div><div class="recommendation-option"><label for="activity-recommendation"><span>Request CHI official recommendation</span><input id="activity-recommendation" name="recommendationRequested" type="checkbox" value="yes" ${d.recommendationRequested?'checked':''} aria-describedby="recommendation-help"></label><p id="recommendation-help">Optional. Needs CHI review and approval.</p></div><label class="form-label" for="activity-place">Meeting point</label><input id="activity-place" name="place" class="input" placeholder="Where to meet" required maxlength="100" value="${esc(d.place)}"><label class="form-label" for="activity-topic">Shared interest</label><select id="activity-topic" name="topic" class="select">${topics.map(t=>`<option value="${t.id}" ${d.topic===t.id?'selected':''}>${t.name}</option>`).join('')}</select><label class="form-label" for="activity-price">Ticket price (USD) · 0 for free</label><input id="activity-price" class="input" type="number" name="price" min="0" max="10000" step="0.01" value="${esc(d.price||0)}" required><label class="form-label" for="activity-description">What should people expect?</label><textarea id="activity-description" name="description" class="input" placeholder="What it’s about, who it’s for and how to join." required maxlength="800">${esc(d.description)}</textarea><div id="create-error" class="form-error" role="alert"></div><p class="create-hint">Please confirm you have permission to use the meeting space.</p></div><div class="create-actions">${btn('Cancel','cancel-create','secondary')}<button type="submit" class="btn">Preview activity ${icon('arrow')}</button></div></form></div>`,'create',{tabs:false,header:false});}
function render(){crowdController?.destroy();crowdController=null;app.classList.toggle('still',lastRoute===route);lastRoute=route;document.title='CHI Together · '+(route.startsWith('event-')?'Activity':route==='welcome'?'Welcome':route.charAt(0).toUpperCase()+route.slice(1));const views={welcome,role:roleView,interests:interestsView,goals:goalsView,secondary:secondaryView,outside:outsideView,badge:badgeView,login:loginView,home:homeView,menu:homeView,events:eventsView,map:mapView,plan:planView,profile:profileView,create:createView};app.innerHTML=route.startsWith('event-')?detailView(route.slice(6)):(views[route]||welcome)();const viewport=document.querySelector('.crowd-viewport');if(viewport)crowdController=mountCrowdMap(viewport,crowdState);syncFilterBar();}
function syncFilterBar(){const bar=document.querySelector('.filters');const on=bar?.querySelector('.active');if(bar&&on)bar.scrollLeft=on.offsetLeft-(bar.clientWidth-on.offsetWidth)/2;}
function showSheet(content,title='Activity information'){sheet.setAttribute('aria-label',title);sheet.innerHTML=`<div class="sheet-header"><span class="eyebrow">CHI Together</span><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><div class="sheet-body">${content}</div>`;if(!sheet.open)sheet.showModal();}
function save(id){if(!getEvent(id))return;const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];persist();if(route==='plan'||sheet.open||route.startsWith('event-'))render();else{syncSaved(id);syncTabCount();}toast(exists?'Removed from your plan':'Saved to your plan');}
function readNames(){const f=document.querySelector('#profile-name'),l=document.querySelector('#profile-last');if(!f)return true;state.profile.name=f.value.trim();state.profile.lastName=(l?.value||'').trim();const em=document.querySelector('#profile-email');if(em)state.profile.email=em.value.trim();const bad=!state.profile.name?f:(l&&!state.profile.lastName?l:(em&&!validEmail(state.profile.email)?em:null));if(bad){bad.focus();bad.setCustomValidity(bad===f?'Enter your first name.':bad===l?'Enter your last name.':'Enter a valid email address.');bad.reportValidity();return false;}persist();return true;}
const validEmail=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v||'');
function showBadge(){if(!state.profile.visible){showSheet(`<h2>Your badge is hidden.</h2><p class="muted">Turn on “Show interest badge” in My badge to show it.</p>${btn('Go to my badge','profile','wide')}`,'Private badge');return;}showSheet(`<div class="badge-hero">${badgeArt()}<h2>${esc(fullName('Alex'))}</h2>${state.profile.position?`<p class="badge-position">${esc(state.profile.position)}</p>`:''}<p>${personalTopics().map(t=>esc(t.name)).join(' × ')}</p></div><p style="margin-top:22px;text-align:center" class="muted">${state.profile.open?'Open to a conversation':'Happy to join and listen'}</p>${btn('Download my badge','download','secondary wide')}`,'My interest badge');}
async function downloadBadge(){try{const selected=personalTopics()[0]||topics[0];const artwork=identitySymbols[selected.icon];const response=await fetch(`assets/identity/${artwork.src}`);if(!response.ok)throw new Error('Artwork unavailable');const blob=new Blob([await response.arrayBuffer()],{type:artwork.src.endsWith('.svg')?'image/svg+xml':'image/png'});const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});const source=`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="760" viewBox="0 0 600 760"><rect width="600" height="760" rx="36" fill="#f5f5f5"/><text x="300" y="70" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="24" fill="#707070">CHI TOGETHER</text><svg x="225" y="155" width="150" height="150" viewBox="${artwork.view}" opacity=".65"><image href="${data}" width="${artwork.w}" height="${artwork.h}"/></svg><text x="300" y="405" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="38" fill="#606060">${esc(fullName('Hello'))}</text><text x="300" y="460" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="22" fill="#777">${esc(selected.name)}</text><text x="300" y="690" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="15" fill="#888">CHI 2027</text></svg>`;const url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='chi-interest-badge.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Your badge is ready to download.');}catch{toast('Your badge could not be downloaded. Please try again.');}}

function priceLabel(e){return e.kind==='paper'?'Included':Number(e.price)>0?`US$${Number(e.price).toFixed(2)}`:'Free';}
function tierOptions(e){return Number(e.price)>0?[{name:'Standard',price:Number(e.price),description:'One place at this gathering.'},{name:'Supporter',price:Number(e.price)+5,description:'One place, with an additional contribution to the gathering.'}]:[{name:'General admission',price:0,description:'One free place at this gathering.'}];}
function openRegistration(id){const e=getEvent(id);if(!e||e.kind==='paper'||['Full','Cancelled'].includes(e.status))return;if(state.registrations[id]){showTicket(id);return;}selectedTier=0;showTicketSelection(id);}
function showTicketSelection(id){const e=getEvent(id);if(!e)return;const tiers=tierOptions(e);showSheet(`<div class="registration-sheet"><h2>Select Ticket</h2><p class="sheet-event-name">${esc(e.title)}</p><div class="ticket-options" role="radiogroup" aria-label="Ticket type">${tiers.map((t,i)=>`<button role="radio" aria-checked="${selectedTier===i}" class="ticket-option ${selectedTier===i?'selected':''}" data-ticket-tier="${i}" data-registration-id="${esc(id)}"><span class="tier-circle">${selectedTier===i?icon('check'):''}</span><span><strong>${t.name}</strong><span class="tier-price">${t.price?`US$${t.price.toFixed(2)}`:'Free'}</span><small>${t.description}</small><small>May ${e.day} · ${e.start}–${e.end}</small></span></button>`).join('')}</div><button class="btn wide" data-registration-review="${esc(id)}">Next ${icon('arrow')}</button></div>`,'Select Ticket');}
function reviewRegistration(id){const e=getEvent(id);if(!e)return;const t=tierOptions(e)[selectedTier]||tierOptions(e)[0];showSheet(`<div class="registration-sheet"><p class="eyebrow">${t.price?'DEMO CHECKOUT':'FREE REGISTRATION'}</p><h2>Review and confirm</h2><div class="registration-summary"><strong>${esc(e.title)}</strong><span>May ${e.day} · ${e.start}–${e.end}</span><span>${esc(e.place)}</span><hr><span>${esc(t.name)} × 1</span><div class="row between"><strong>Total</strong><strong>${t.price?`US$${t.price.toFixed(2)}`:'Free'}</strong></div></div>${t.price?'<p class="demo-note">Simulated payment · You won’t be charged.</p>':''}<button class="btn wide" data-confirm-registration="${esc(id)}">${t.price?`Simulate payment · US$${t.price.toFixed(2)}`:'Confirm free registration'}</button><button class="text-button wide" data-registration-back="${esc(id)}">Back to ticket selection</button></div>`,t.price?'Demo checkout':'Confirm registration');}
function confirmDemoRegistration(id){const e=getEvent(id);if(!e||e.kind==='paper'||['Full','Cancelled'].includes(e.status))return;if(!state.registrations[id]){const t=tierOptions(e)[selectedTier]||tierOptions(e)[0];state.registrations[id]={code:'CHI-'+crypto.randomUUID().slice(0,8).toUpperCase(),tier:t.name,price:t.price,holder:state.profile.name||'Guest',registeredAt:new Date().toISOString()};if(!state.saved.includes(id))state.saved.push(id);persist();render();}showRegistrationSuccess(id);}
function showRegistrationSuccess(id){const e=getEvent(id);showSheet(`<div class="registration-success"><span class="registration-check">${icon('check')}</span><h2>You’re registered.</h2><p>${esc(e.title)}</p><p class="small muted">Add it to your calendar so you don’t miss it.</p><button class="btn wide" data-calendar="${esc(id)}">${icon('calendar')} Add to Calendar</button><button class="btn secondary wide" data-wallet="${esc(id)}">${icon('bookmark')} Add to Wallet · Preview</button><button class="text-button wide" data-ticket="${esc(id)}">View my demo ticket ${icon('arrow')}</button></div>`,'Registration complete');}
function ticketMarkup(e,r){return `<div class="demo-ticket"><span class="eyebrow">CHI TOGETHER · DEMO TICKET</span><div class="ticket-mini-cover">${eventCover(e)}</div><h3>${esc(e.title)}</h3><p>May ${e.day} · ${e.start}–${e.end}</p><p>${esc(e.place)}</p><div class="ticket-perforation"></div><div class="ticket-holder"><span><small>GUEST</small><strong>${esc(r.holder)}</strong></span><span><small>${esc(r.tier)}</small><strong>${r.price?`US$${r.price.toFixed(2)}`:'Free'}</strong></span></div><code>${esc(r.code)}</code><small class="ticket-validity">Preview only · Not valid for admission.</small></div>`;}
function showTicket(id){const e=getEvent(id),r=state.registrations[id];if(!e||!r||e.kind==='paper')return;showSheet(`<h2>My Ticket</h2>${ticketMarkup(e,r)}<button class="btn wide" data-calendar="${esc(id)}">${icon('calendar')} Add to Calendar</button><button class="btn secondary wide" data-wallet="${esc(id)}">${icon('bookmark')} ${state.wallet[id]?'View demo Wallet pass':'Add to Wallet · Preview'}</button>`,'My Ticket');}
function showWallet(id){const e=getEvent(id),r=state.registrations[id];if(!e||!r||e.kind==='paper')return;showSheet(`<div class="wallet-preview"><h2>Wallet pass</h2>${ticketMarkup(e,r)}<p class="demo-note">Saved inside this prototype only.</p><button class="btn wide" data-wallet-save="${esc(id)}">${state.wallet[id]?'Saved to demo wallet':'Save to demo wallet'}</button></div>`,'Wallet preview');}
function showCalendar(id){const e=getEvent(id);if(!e)return;showSheet(`<div class="calendar-sheet"><h2>Add to calendar</h2><div class="calendar-event-summary"><strong>${esc(e.title)}</strong><span>May ${e.day} · ${e.start}–${e.end}</span><small>Pittsburgh time · EDT</small></div><a class="btn wide" href="${esc(googleCalendarUrl(e))}" target="_blank" rel="noopener noreferrer">Google Calendar ${icon('arrow')}</a><button class="btn secondary wide" data-calendar-download="${esc(e.id)}">Apple / Outlook ${icon('download')}</button></div>`,'Add to calendar');}
function exportCalendar(id){const e=getEvent(id);if(!e)return;const contents=buildCalendarFile(e,state.calendarPrefs.reminder);downloadArtifact(contents,'text/calendar;charset=utf-8',`chi-${e.id.replace(/[^a-z0-9-]/gi,'')}.ics`);if(!state.saved.includes(id)){state.saved.push(id);persist();render();}toast('Calendar file prepared. Open it in your calendar app to save.');}
function downloadArtifact(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function showShare(id){const e=getEvent(id);if(!e)return;const url=location.origin+location.pathname+'#event-'+encodeURIComponent(id);showSheet(`<div class="share-event-sheet"><h2>Share Event</h2><label class="share-link"><input aria-label="Event link" readonly value="${esc(url)}"><button class="icon-button" data-copy-event="${esc(id)}" aria-label="Copy event link">${icon('bookmark')}</button></label><div class="share-event-card">${eventCover(e)}<h3>${esc(e.title)}</h3><p>May ${e.day} · Pittsburgh</p><span>CHI Together</span></div><button class="btn wide" data-share-native="${esc(id)}">${icon('share')} Share Event</button><button class="text-button wide" data-copy-event="${esc(id)}">Copy link</button></div>`,'Share Event');}
async function copyEventLink(id){const url=location.origin+location.pathname+'#event-'+encodeURIComponent(id);try{await navigator.clipboard.writeText(url);toast('Event link copied.');}catch{sheet.querySelector('input')?.select();toast('Select and copy the event link above.');}}
function showEventMore(id){const e=getEvent(id);if(!e)return;showSheet(`<h2>More options</h2><div class="event-more-list"><button data-save="${esc(id)}">${icon('bookmark')}${state.saved.includes(id)?'Remove from my plan':'Save to my plan'}</button><button data-share="${esc(id)}">${icon('share')}Share event</button><button data-calendar="${esc(id)}">${icon('calendar')}Add to Calendar</button>${state.registrations[id]?`<button data-cancel-registration="${esc(id)}">${icon('close')}Cancel demo registration</button>`:''}</div>`,'Activity options');}
function handleEventWorkflow(el){
 if(el.dataset.save&&sheet.open){save(el.dataset.save);showEventMore(el.dataset.save);return true;}
 if(el.dataset.homeFilter){filter=el.dataset.homeFilter;search='';day='all';navigate('events');return true;}
 if(el.dataset.register){openRegistration(el.dataset.register);return true;}
 if(el.dataset.ticketTier!==undefined){selectedTier=Number(el.dataset.ticketTier);showTicketSelection(el.dataset.registrationId);return true;}
 if(el.dataset.registrationReview){reviewRegistration(el.dataset.registrationReview);return true;}
 if(el.dataset.registrationBack){showTicketSelection(el.dataset.registrationBack);return true;}
 if(el.dataset.confirmRegistration){confirmDemoRegistration(el.dataset.confirmRegistration);return true;}
 if(el.dataset.ticket){showTicket(el.dataset.ticket);return true;}
 if(el.dataset.calendar){showCalendar(el.dataset.calendar);return true;}
 if(el.dataset.calendarDownload){exportCalendar(el.dataset.calendarDownload);return true;}
 if(el.dataset.wallet){showWallet(el.dataset.wallet);return true;}
 if(el.dataset.walletSave){const id=el.dataset.walletSave;if(getEvent(id)?.kind==='paper'||!state.registrations[id])return true;state.wallet[id]={savedAt:new Date().toISOString()};persist();showWallet(id);toast('Saved in the demo wallet. Your device Wallet is unchanged.');return true;}
 if(el.dataset.share){showShare(el.dataset.share);return true;}
 if(el.dataset.copyEvent){copyEventLink(el.dataset.copyEvent);return true;}
 if(el.dataset.shareNative){const e=getEvent(el.dataset.shareNative);const url=location.origin+location.pathname+'#event-'+encodeURIComponent(e.id);if(navigator.share)navigator.share({title:e.title,text:'Join a gathering at CHI.',url}).catch(error=>{if(error.name!=='AbortError')copyEventLink(e.id);});else copyEventLink(e.id);return true;}
 if(el.dataset.eventMore){showEventMore(el.dataset.eventMore);return true;}
 if(el.dataset.contact){const e=getEvent(el.dataset.contact);showSheet(`<h2>Contact host</h2><div class="event-host-block">${hostIdentity(e)}</div><p class="detail-copy">Meeting point: ${esc(e.place)}.</p><p class="demo-note">Host messaging is not connected in this prototype.</p>`,'Contact host');return true;}
 if(el.dataset.cancelRegistration){const id=el.dataset.cancelRegistration;showSheet(`<h2>Cancel your demo ticket?</h2><p class="muted">This removes the registration and demo Wallet pass. Your personal plan is kept.</p><button class="btn wide" data-confirm-cancel-registration="${esc(id)}">Cancel demo registration</button><button class="btn secondary wide" data-ticket="${esc(id)}">Keep my ticket</button>`,'Cancel demo registration');return true;}
 if(el.dataset.confirmCancelRegistration){const id=el.dataset.confirmCancelRegistration;delete state.registrations[id];delete state.wallet[id];persist();sheet.close();render();toast('Demo registration cancelled.');return true;}
 return false;
}
document.addEventListener('change',event=>{const el=event.target;if(!['calendar-provider','calendar-reminder'].includes(el.id))return;state.calendarPrefs[el.id==='calendar-provider'?'provider':'reminder']=el.value;persist();const e=getEvent(sheet.dataset.calendarEvent);if(e)document.querySelector('#calendar-action').innerHTML=calendarActionMarkup(e);});

const actions={
  secondary:()=>{if(!state.profile.topics.length){toast('Choose a domain interest first.');return;}navigate('secondary');},outside:()=>navigate('outside'),
  start:()=>navigate('role'),welcome:()=>navigate('welcome'),role:()=>navigate('role'),interests:()=>navigate('interests'),
  goals:()=>{if(!readNames())return;persist();navigate('goals');},
  'make-badge':()=>{if(!state.profile.topics.length){toast('Choose at least one interest.');return;}if(!readNames())return;persist();navigate('badge');},
  'change-avatar':()=>document.querySelector('#avatar-file')?.click(),
  finish:()=>{if(!readNames())return;state.complete=true;persist();navigate(profileEdit?'profile':'home',false,true);profileEdit=false;},
  login:()=>{loginSent=false;navigate('login');},'login-retry':()=>{loginSent=false;render();},'send-link':()=>{const f=document.querySelector('#login-email');if(!validEmail(f?.value.trim())){f.setCustomValidity('Enter a valid email address.');f.reportValidity();f.focus();return;}loginEmail=f.value.trim();loginSent=true;render();},resume:()=>{if(!state.complete){state.profile={...state.profile,email:loginEmail||'alex@example.com',name:'Alex',lastName:'Chen',topics:['health'],personalInterests:['coffee']};state.complete=true;persist();}navigate('home');},
  menu:()=>navigate('home'),back:()=>goBack(['role','interests','goals','secondary','outside','badge','login'].includes(route)?'welcome':'home'),home:()=>navigate('home'),events:()=>navigate('events'),map:()=>navigate('map'),plan:()=>navigate('plan'),profile:()=>navigate('profile'),create:()=>navigate('create'),
  'edit-interests':()=>{profileEdit=true;navigate('goals');},'show-badge':showBadge,download:downloadBadge,
  'close-sheet':()=>sheet.close(),'clear-filters':()=>{search='';filter='all';day='all';render();},
  'stage-toggle':()=>{state.stage=state.stage==='before'?'during':'before';persist();render();},
  'cancel-create':()=>{draft=null;goBack('events');},
  publish:()=>{if(!draft)return;const t=topic(draft.topic);const item={...draft,id:'local-'+crypto.randomUUID(),type:'Community gathering',tags:[draft.topic],icon:t.icon,capacity:Number(draft.capacity),count:0,status:'Drop in',x:50,y:50,floor:1,local:true,expect:'Registration is required, including for free admission. Confirm meeting instructions and accessibility arrangements with the host.'};state.custom.push(item);state.saved.push(item.id);persist();draft=null;search='';filter='all';day='all';showSheet(`<div style="text-align:center"><div class="success-symbol">${icon('check')}</div><h2>Activity created.</h2><p class="muted">It’s now in Activities and your plan.</p>${btn('View activity','published-view','wide',`data-id="${item.id}"`)}${btn('Back to activities','events','secondary wide')}</div>`,'Activity created');},
  'published-view':el=>navigate('event-'+el.dataset.id,false,true),
  reset:()=>showSheet(`<h2>Reset prototype?</h2><p class="muted">This clears your profile, saved activities and locally created gatherings from this browser.</p>${btn('Reset prototype','confirm-reset','wide')}${btn('Cancel','close-sheet','secondary wide')}`,'Reset prototype'),
  'confirm-reset':()=>{state=structuredClone(defaults);draft=null;persist();navigate('welcome');},
};
document.addEventListener('click',event=>{
  const el=event.target.closest('button, a');if(!el)return;
  if(handleCrowdMapAction(el))return;
  if(handleEventWorkflow(el))return;
  if(el.dataset.action){actions[el.dataset.action]?.(el);return;}
  if(el.dataset.role){state.profile.role=el.dataset.role;persist();navigate('interests');return;}
  if(el.dataset.personalInterest){const id=el.dataset.personalInterest;const list=state.profile.personalInterests;if(list.includes(id))state.profile.personalInterests=list.filter(t=>t!==id);else if(list.length<2)list.push(id);else{toast('Choose up to two personal interests.');return;}persist();syncChips();return;}
  if(el.dataset.secondaryInterest){const id=el.dataset.secondaryInterest;const selected=state.profile.secondaryInterests;if(selected.includes(id))state.profile.secondaryInterests=selected.filter(t=>t!==id);else if(selected.length<2)selected.push(id);else{toast('Choose up to two secondary interests.');return;}persist();syncChips();return;}
  if(el.dataset.topic){state.profile.topics=[el.dataset.topic];state.profile.secondaryInterests=state.profile.secondaryInterests.filter(t=>t!==el.dataset.topic);persist();syncChips();return;}
  if(el.dataset.save){save(el.dataset.save);return;}
  if(el.dataset.event){navigate('event-'+el.dataset.event);return;}
  if(el.dataset.filter){filter=el.dataset.filter;document.querySelectorAll('.filter').forEach(n=>{const on=n.dataset.filter===filter;n.classList.toggle('active',on);n.setAttribute('aria-pressed',String(on));});document.querySelector('#event-results').innerHTML=resultsMarkup();el.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'});return;}
  if(el.dataset.stage){state.stage=el.dataset.stage;persist();render();return;}
  if(el.dataset.floor){floor=Number(el.dataset.floor);render();return;}
  if(el.dataset.mapMode){mapMode=el.dataset.mapMode;render();return;}
  if(el.dataset.point){selectedPoint=el.dataset.point;mapMode='selected';render();return;}
  if(el.dataset.locate){const e=getEvent(el.dataset.locate);crowdState.activities=true;crowdState.focus={x:e.x,y:e.y,zoom:2.2};navigate('map');return;}
  if(el.dataset.cancel){const e=state.custom.find(x=>x.id===el.dataset.cancel);if(e){e.status=e.status==='Cancelled'?'Drop in':'Cancelled';persist();render();toast(e.status==='Cancelled'?'Activity marked as cancelled.':'Activity restored.');}return;}
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='avatar-file'){const file=el.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PNG, JPG or WebP image under 2 MB.');return;}const reader=new FileReader();reader.onload=()=>{state.profile.avatar=String(reader.result);persist();render();};reader.readAsDataURL(file);}if(el.dataset.goal){el.closest('.wf-goal')?.classList.toggle('selected',el.checked);state.profile.goals=el.checked?[...new Set([...state.profile.goals,el.dataset.goal])]:state.profile.goals.filter(g=>g!==el.dataset.goal);persist();}if(['open-chat','profile-open'].includes(el.id)){state.profile.open=el.checked;persist();if(el.id==='profile-open')render();}if(['badge-visible','profile-visible'].includes(el.id)){state.profile.visible=el.checked;persist();}if(el.id==='day-filter'){day=el.value;render();}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='profile-name'){el.setCustomValidity('');state.profile.name=el.value;persist();}if(el.id==='profile-last'){el.setCustomValidity('');state.profile.lastName=el.value;persist();}if(el.id==='profile-email'){el.setCustomValidity('');state.profile.email=el.value;persist();}if(el.id==='login-email'){el.setCustomValidity('');loginEmail=el.value;}if(el.id==='profile-bio'){state.profile.bio=el.value;persist();}if(el.id==='event-search'){search=el.value;document.querySelector('#event-results').innerHTML=resultsMarkup();}});
document.addEventListener('submit',event=>{if(event.target.id!=='create-form')return;event.preventDefault();const form=event.target;const values=Object.fromEntries(new FormData(form));const error=document.querySelector('#create-error');if(values.end<=values.start){error.textContent='The end time should be after the start time.';return;}if(!values.title.trim()||!values.place.trim()||!values.description.trim()){error.textContent='Add an activity name, meeting point, and description.';return;}draft={...values,recommendationRequested:values.recommendationRequested==='yes',recommendationStatus:values.recommendationRequested==='yes'?'pending':'not-requested',title:values.title.trim(),place:values.place.trim(),description:values.description.trim(),host:state.profile.name||'Alex'};showSheet(`<p class="eyebrow" style="margin-bottom:12px">Activity preview</p><h2>${esc(draft.title)}</h2><div class="info-row">${icon('clock')}<div><strong>May ${draft.day} · ${draft.start}–${draft.end}</strong><small>Pittsburgh time</small></div></div><div class="info-row">${icon('pin')}<div><strong>${esc(draft.place)}</strong><small>Capacity ${draft.capacity} · Registration required</small></div></div><p class="muted" style="margin:20px 0">${esc(draft.description)}</p>${tags([draft.topic])}<div class="recommendation-preview"><strong>${draft.recommendationRequested?'CHI recommendation · Pending approval (demo)':'CHI recommendation · Not requested'}</strong><p>${draft.recommendationRequested?'Review and approval are required before this event can be officially recommended. This prototype does not send a request to CHI.':'This event will remain a community activity.'}</p></div>${btn('Create sample activity','publish','wide')}${btn('Keep editing','close-sheet','secondary wide')}`,'Preview activity');});
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sheet.close();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'welcome';if(next!==route){if(sheet.open)sheet.close();if(trail[trail.length-1]===next)trail.pop();scrollMemo[route]=window.scrollY;route=next;render();window.scrollTo(0,scrollMemo[next]||0);}});
render();
